def __new__(cls, cid, *, _unbound=None):
if _unbound is None:
try:
op = _channels.get_channel_defaults(cid)
_unbound = (op,)
except ChannelNotFoundError:
_unbound = _serialize_unbound(UNBOUND)
self = super().__new__(cls, cid)
self._unbound = _unbound
return self

A doubly-linked list that can be embedded in a struct.

Usage:
struct llist_node head = LLIST_INIT(head);
typedef struct {
...
struct llist_node node;
...
} MyObj;

llist_insert_tail(&head, &obj->node);
llist_remove(&obj->node);

struct llist_node *node;
llist_for_each(node, &head) {
MyObj *obj = llist_data(node, MyObj, node);
...
}
